// Zwei Erkundungen in einem Knoten:
//   1. Feldbestand von /v2/invoice/{id}/data fuer acht Rechnungen
//   2. gibt die Rechnungsliste erneut aus, damit die Datenbank vergleichen kann

const auth = $('S24 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

async function abruf(pfad, qs) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: `https://app1.edoobox.com/v2${pfad}`,
    headers,
    qs,
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });
}

const hole = abruf.bind(this);

function liste(h) {
  if (!h || typeof h !== 'object') return [];
  const d = h.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

function zahl(w) {
  if (w === null || w === undefined || w === '' || w === false) return null;
  const n = Number(String(w).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}

function zeitpunkt(w) {
  return typeof w === 'string' && /^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(w) ? w : null;
}

// Alle Rechnungen einsammeln
const alle = [];
let start = 0;
for (let i = 0; i < 20; i += 1) {
  const a = await hole('/invoice/list', { 'limit[start]': start, 'limit[reply]': 2000 });
  if (a.statusCode !== 200) throw new Error(`invoice/list Status ${a.statusCode}`);
  const d = liste(a.body);
  alle.push(...d);
  if (d.length < 2000) break;
  start += 2000;
}

const saetze = alle.filter((r) => r && r.id).map((r) => ({
  invoice_id: String(r.id),
  paytrans: r.paytrans ? String(r.paytrans) : null,
  user_ref_roh: r.user ? String(r.user) : null,
  invoice_number: r.number ? String(r.number) : null,
  amount: zahl(r.amount),
  status: zahl(r.status),
  date_create: zeitpunkt(r.date_create),
  offer_start_date: zeitpunkt(r.offer_start_date),
}));

// Feldbestand der Einzelrechnung. Acht moeglichst verschiedene Faelle.
const proben = [];
for (const s of [1, 2, 3].map((n) => saetze.find((x) => x.status === n)).filter(Boolean)) proben.push(s);
for (const s of saetze.slice(-3)) if (!proben.includes(s)) proben.push(s);
for (const s of saetze) {
  if (proben.length >= 8) break;
  if (!proben.includes(s)) proben.push(s);
}

function art(w) {
  if (w === null) return 'null';
  if (Array.isArray(w)) return `liste[${w.length}]`;
  if (typeof w === 'object') return `objekt{${Object.keys(w).slice(0, 14).join(',')}}`;
  if (typeof w === 'boolean') return `wahrheitswert:${w}`;
  if (typeof w === 'number') return 'zahl';
  if (typeof w === 'string') {
    if (w === '') return 'text:leer';
    if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(w)) return 'text:zeitpunkt';
    return `text(${w.length})`;
  }
  return typeof w;
}

const offen = /id$|_id|ref|booking|offer|order|trans|vat|ust|tax|steuer|mwst|rate|satz|net|gross|brutto|netto|amount|betrag|total|status|type|art|number|nummer|country|land|currency/i;

const felder = new Map();
let gelesen = 0;
let fehler = '';

for (const p of proben) {
  const a = await hole(`/invoice/${encodeURIComponent(p.invoice_id)}/data`, {});
  if (a.statusCode !== 200) {
    if (!fehler) fehler = `Status ${a.statusCode}`;
    continue;
  }
  const roh = a.body?.data;
  const r = Array.isArray(roh) ? roh[0] : roh;
  if (!r || typeof r !== 'object') continue;
  gelesen += 1;
  for (const [feld, wert] of Object.entries(r)) {
    if (!felder.has(feld)) felder.set(feld, { feld, arten: new Set(), werte: new Set() });
    const e = felder.get(feld);
    e.arten.add(art(wert));
    if (offen.test(feld) && (typeof wert !== 'object' || wert === null)) {
      const t = String(wert);
      if (t.length <= 40) e.werte.add(t);
    }
  }
}

const zeilen = [{
  json: {
    schritt: 'S24',
    bereich: 'Einzelrechnung',
    feld: '(Probe)',
    arten: `${gelesen} von ${proben.length} gelesen${fehler ? ', Fehler: ' + fehler : ''}`,
    beispielwerte: '',
    datenJson: JSON.stringify(saetze),
  },
}];

for (const e of [...felder.values()].sort((a, b) => a.feld.localeCompare(b.feld))) {
  zeilen.push({
    json: {
      schritt: 'S24',
      bereich: 'Einzelrechnung',
      feld: e.feld,
      arten: [...e.arten].slice(0, 4).join(' | '),
      beispielwerte: [...e.werte].slice(0, 6).join(' | '),
      datenJson: '',
    },
  });
}

return zeilen;
